inline constexpr int ISO_METRIC_THREADS_COUNT = int(sizeof(ISO_METRIC_THREADS) / sizeof(ISO_METRIC_THREADS[0]));

inline bool iso_metric_thread_valid(int idx) { return idx >= 0 && idx < ISO_METRIC_THREADS_COUNT; }

// Désignation au gros pas de la taille nominale la plus proche du diamètre donné.
inline int iso_metric_thread_closest(double diameter)
{
    int    best      = 0;
    double best_dist = 1e30;
    for (int i = 0; i < ISO_METRIC_THREADS_COUNT; ++i) {
        // la première désignation d'une taille est son gros pas
        if (i > 0 && ISO_METRIC_THREADS[i].size == ISO_METRIC_THREADS[i - 1].size)
            continue;
        const double dist = std::abs(ISO_METRIC_THREADS[i].size - diameter);
        if (dist < best_dist) {
            best      = i;
            best_dist = dist;
        }
    }
    return best;
}

// Diamètres (majeur, sur flancs, mineur) d'une désignation : vis selon la classe (0 = 6g, 1 = 4g6g),
// ou écrou (6H).
inline const double *iso_metric_thread_diameters(int idx, bool external, int thread_class)
{
    const IsoMetricThread &t = ISO_METRIC_THREADS[iso_metric_thread_valid(idx) ? idx : 0];
    return external ? (thread_class == 1 ? t.ext_4g6g : t.ext_6g) : t.int_6H;
}

